```javascript
// Importer le package Discord.js v14
const { Client, GatewayIntentBits, SlashCommandBuilder } = require('discord.js');

// Créer une instance du client Discord.js
const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent
  ]
});

// Connexion du client au serveur Discord
client.once('ready', () => {
  console.log('Bot Discord prêt !');
});

// Commande "bannir" créée à l'aide d'un bâtiment de commandes slash
const banCommand = new SlashCommandBuilder()
  .setName('ban')
  .setDescription('Bannir un utilisateur du serveur')
  .addUserOption(option =>
    option.setName('utilisateur')
      .setDescription('L\'utilisateur à bannir')
      .setRequired(true)
  )
  .addStringOption(option =>
    option.setName('raison')
      .setDescription('La raison du bannissement')
      .setRequired(true)
  );

// Ajouter la commande "bannir" au client Discord.js
client.commandData.push(banCommand);

// Écouter les événements de la commande "bannir"
client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  if (interaction.commandName === 'ban') {
    const user = interaction.options.getUser('utilisateur');
    const reason = interaction.options.getString('raison');

    // Vérifier si l'utilisateur a la permission de bannir
    if (!interaction.memberPermissions.has('BAN_MEMBERS')) {
      return interaction.reply({ content: 'Vous n\'avez pas la permission de bannir les utilisateurs.', ephemeral: true });
    }

    // Vérifier si le bot a la permission de bannir
    if (!interaction.guild.members.me.permissions.has('BAN_MEMBERS')) {
      return interaction.reply({ content: 'Le bot n\'a pas la permission de bannir les utilisateurs.', ephemeral: true });
    }

    try {
      await interaction.guild.members.ban(user, { reason });
      return interaction.reply({ content: `**${user.tag}** a été banni avec la raison "${reason}".`, ephemeral: false });
    } catch (error) {
      console.error(error);
      return interaction.reply({ content: 'Une erreur est survenue lors du bannissement de l\'utilisateur.', ephemeral: true });
    }
  }
});

// Connexion du client au serveur Discord
client.login(process.env.DISCORD_TOKEN);
```

Remarque : Assurez-vous de remplacer `process.env.DISCORD_TOKEN` par votre propre token Discord. Pour obtenir un token Discord, vous devez d'abord créer un compte bot sur le site officiel de Discord (https://discord.com/developers/applications) et donner les permissions appropriées à votre bot dans votre serveur Discord. Ensuite, générer un token pour votre bot et le placer dans un environnement de développement tel qu'un fichier `.env`. Cela vous permettra de protéger votre token de votre code source.

