Voici une fonction C++ qui prend une référence à un std::string contenant du texte au format Markdown et renvoie un std::string contenant du texte au format HTML :

```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <regex>

// Fonction de conversion Markdown -> HTML
std::string convertMarkdownToHtml(const std::string& markdown) {
    std::stringstream ss;
    std::string html;

    // Titres
    std::regex title_regex("^#{1,6} (. *)$");
    if (std::regex_match(markdown, title_regex)) {
        std::string title = std::regex_replace(markdown, title_regex, "$1");
        html += "<h" + std::to_string(title.length()) + ">" + title + "</h" + std::to_string(title.length()) + ">\n";
    } else {
        ss << markdown;
    }

    // Gras et italique
    std::regex italic_regex("(_([^_]+)_)|(\*([^*]+)\*)");
    while (std::regex_search(ss.str(), italic_regex, std::regex_constants::match_continuous)) {
        std::string type;
        std::string content;

        if (std::regex_match(ss.str(), italic_regex, std::smatch& match)) {
            type = match[1].str().length() == 2 ? "em" : "strong";
            content = match[2].str();
        }

        html += "<" + type + ">" + content + "</" + type + ">\n";
        ss.str("");
    }

    // Lien
    std::regex link_regex("\\[([^\\]]+)]\\(([^\\)]+)\\)");
    while (std::regex_search(ss.str(), link_regex, std::regex_constants::match_continuous)) {
        std::string link_text = std::regex_replace(ss.str(), link_regex, "$1");
        std::string link_url = std::regex_replace(ss.str(), link_regex, "$2");
        html += "<a href=\"" + link_url + "\">" + link_text + "</a>\n";
        ss.str("");
    }

    // Bloc de code
    std::regex code_block_regex("^(`{3}|~{3}) (. *) $(`{3}|~{3})$");
    if (std::regex_match(markdown, code_block_regex)) {
        std::string code = std::regex_replace(markdown, code_block_regex, "$2");
        html += "<pre><code>" + code + "</code></pre>\n";
    } else {
        ss << markdown;
    }

    // Retourner le contenu HTML
    while (std::getline(ss, html)) {
        // Ajouter les balises HTML manquantes
        std::regex paragraph_regex("^([^\n]+)$");
        if (std::regex_match(html, paragraph_regex)) {
            html = "<p>" + html + "</p>\n";
        }
    }

    return html;
}

int main() {
    std::string markdown = "Hello **world**! \n\n # Titre h1 \n## Titre h2\n### Titre h3\n\n [lien](https://example.com) \n\n `code` ";
    std::string html = convertMarkdownToHtml(markdown);
    std::cout << html << std::endl;

    return 0;
}
```

Cette fonction utilise la bibliothèque standard C++ pour effectuer la conversion de Markdown vers HTML. Elle utilise des expressions régulières pour détecter les différents éléments Markdown (titres, gras et italique, liens, blocs de code) et les convertir en HTML correspondants. Elle utilise également un flux de sortie pour gérer les différentes lignes de texte dans le Markdown et ajouter les balises HTML manquantes. 

Vous pouvez utiliser cette fonction en appelant la fonction `convertMarkdownToHtml` avec une chaîne de caractères contenant du texte au format Markdown. Elle renvoie une chaîne de caractères contenant le texte au format HTML correspondant.

