    if (head->x < 0 || head->x >= game->width || head->y < 0 || head->y >= game->height) {
        return true;
    }

    for (int I = 1; I < game->snake_length; i++) {
        if (head->x == game->snake[i].x && head->y == game->snake[i].y) {
