14. Gère l'actualisation du jeu et la fermeture de la fenêtre :

```c
void handle_events(Game* game) {
    SDL_Event event;
    while (SDL_PollEvent(&event)) {
        switch (event.type) {
            case SDL_QUIT:
                game->running = false;
                break;
            case SDL_KEYDOWN:
                handle_keypress(event.key.keysym.sym, game);
                break;
        }
    }
}

void update_game(Game* game) {
    move_snake(game);

    if (check_collision(&game->snake[0], game->apple_x, game->apple_y)) {
        game->snake_length++;
        game->score++;
        game->apple_x = rand() % (game->width / 20) * 20;
        game->apple_y = rand() % (game->height / 20) * 20;
    }

    if (is_game_over(game)) {
        game->running = false;
    }
}

int main() {
    const int WINDOW_WIDTH = 800;
    const int WINDOW_HEIGHT = 600;

    Game game;
    init_game(&game, WINDOW_WIDTH, WINDOW_HEIGHT);

    load_textures(&game);

    bool running = true;

    while (running) {
        handle_events(&game);

        SDL_RenderClear(game.renderer);
        draw_game(&game);
        SDL_RenderPresent(game.renderer);

        SDL_Delay(16);

        update_game(&game);
    }

    for (int I = 0; I < game.snake_length; i++) {
        SDL_DestroyTexture(game.snake[i].texture);
    }
    SDL_DestroyTexture(game.apple.texture);

    SDL_DestroyRenderer(game.renderer);
    SDL_DestroyWindow(game.window);

    free(game.snake);

    SDL_Quit();
    IMG_Quit();

    return 0;
}
